installer-gui-script.script:
function bandwidthPlusInstalled() {
    var id = '@BANDWIDTH_PLUS_ID@';
    var running = system.applications.fromIdentifier(id);
    if (running && running.length > 0) {
        return true;
    }
    var home = system.env.HOME || '';
    var paths = ['/Applications/Bandwidth+.app', home + '/Applications/Bandwidth+.app'];
    for (var i = 0; i < paths.length; i++) {
        var info = system.files.bundleAtPath(paths[i]);
        if (info && info.CFBundleIdentifier == id) {
            return true;
        }
    }
    return home != '' && system.files.fileExistsAtPath(home + '/Library/Containers/' + id + '/Data');
}

function bandwidthPlusCheck() {
    if (bandwidthPlusInstalled()) {
        return true;
    }
    my.result.type = 'Warning';
    my.result.title = 'Bandwidth+ isn\'t installed';
    my.result.message = 'Bandwidth Meter reads the daily history that Bandwidth+ records, so install it from the Mac App Store to keep the totals current: https://apps.apple.com/app/bandwidth/id490461369\n\nWithout it, Import CSV in the menu bar panel still works with a History.csv exported from Bandwidth+ on another Mac. Click Continue to install Bandwidth Meter anyway.';
    return false;
}
